def expand(histogram):
    return [value for value, count in histogram for _ in range(count)]


def synthesize():
    table = []
    for dispatcher, _stratum, count, mods, keys, flags, args, labels in POOLS:
        mods, keys, flags, args, labels = map(expand, (mods, keys, flags, args, labels))
        for index in range(count):
            key, keycode = keys[index]
            locked, mouse, release, repeat, described = flags[index]
            table.append({
                "locked": locked, "mouse": mouse, "release": release,
                "repeat": repeat, "longPress": False, "non_consuming": False,
                "auto_consuming": False, "has_description": described,
                "modmask": mods[index], "submap": "", "submap_universal": "false",
                "key": key, "keycode": keycode, "catch_all": False,
                "description": labels[index] if described else "",
                "allow_input_capture": False, "dispatcher": dispatcher,
                "arg": args[index],
            })
    return table


if __name__ == "__main__":
    if len(sys.argv) != 3 or sys.argv[1] != "--home":
        raise SystemExit("usage: K4NoReader.py --home DIR")
    print(json.dumps(synthesize(), separators=(",", ":")))
